#!/usr/bin/env node
/**
 * generate-skill-docs.mjs
 *
 * Rewrites the autogenerated sections of the google-sheets-expert skill bundle
 * using the counts/annotations in src/generated/. Hand-maintained prose is
 * preserved outside the marker comments:
 *
 *     <!-- BEGIN:AUTOGEN <section> -->  ... (overwritten) ...  <!-- END:AUTOGEN <section> -->
 *
 * Sections maintained:
 *   counts  — total tool/action counts
 *   tools   — markdown table of tools with action counts and titles
 *
 * Run via `npm run skill:docs` (chained into schema:commit).
 *
 * The script reads action-counts.ts / annotations.ts as TS source (no import
 * transform needed) using tiny hand-rolled parsers — this keeps the tool
 * dependency-free and compatible with either dist/ builds or pre-build state.
 */

import { readFile, writeFile, rename } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const REPO_ROOT = join(__dirname, '..');

const ACTION_COUNTS_PATH = join(REPO_ROOT, 'src/generated/action-counts.ts');
const ANNOTATIONS_PATH = join(REPO_ROOT, 'src/generated/annotations.ts');
const SKILL_DIR = join(REPO_ROOT, '.claude/skills/google-sheets-expert');
const SKILL_PATH = join(SKILL_DIR, 'SKILL.md');
const GUIDE_PATH = join(SKILL_DIR, 'references/tool-guide.md');

/**
 * Parse the ACTION_COUNTS object from action-counts.ts without requiring a TS build.
 * Expected shape:
 *   export const ACTION_COUNTS: Record<string, number> = {
 *     sheets_advanced: 31,
 *     ...
 *   };
 */
async function readActionCounts() {
  const src = await readFile(ACTION_COUNTS_PATH, 'utf8');
  const body = src.match(/ACTION_COUNTS[^=]*=\s*\{([\s\S]*?)\};/);
  if (!body) throw new Error(`Could not find ACTION_COUNTS in ${ACTION_COUNTS_PATH}`);
  const counts = {};
  for (const line of body[1].split('\n')) {
    const m = line.match(/^\s*([a-zA-Z0-9_]+)\s*:\s*(\d+)\s*,?/);
    if (m) counts[m[1]] = Number(m[2]);
  }
  if (Object.keys(counts).length === 0) {
    throw new Error('ACTION_COUNTS body parsed empty — check the regex');
  }
  return counts;
}

/**
 * Parse TOOL_ANNOTATIONS from annotations.ts to pick up each tool's human title.
 */
async function readToolTitles() {
  if (!existsSync(ANNOTATIONS_PATH)) return {};
  const src = await readFile(ANNOTATIONS_PATH, 'utf8');
  const titles = {};
  // Match pattern:
  //   sheets_auth: {
  //     title: 'Authentication & Setup',
  const re = /([a-z_][a-z0-9_]*)\s*:\s*\{\s*title:\s*'([^']+)'/g;
  let m;
  while ((m = re.exec(src)) !== null) {
    titles[m[1]] = m[2];
  }
  return titles;
}

function renderCountsBlock(counts) {
  const toolCount = Object.keys(counts).length;
  const actionCount = Object.values(counts).reduce((s, n) => s + n, 0);
  return `ServalSheets ships **${toolCount} tools** exposing **${actionCount} actions** across the Google Sheets surface.`;
}

function renderCountsInline(counts) {
  const toolCount = Object.keys(counts).length;
  const actionCount = Object.values(counts).reduce((s, n) => s + n, 0);
  return `ServalSheets exposes **${toolCount} tools** / **${actionCount} actions** over the MCP interface.`;
}

function renderToolTable(counts, titles) {
  const rows = Object.entries(counts)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([tool, n]) => `| \`${tool}\` | ${n} | ${titles[tool] ?? ''} |`);
  return [
    '| Tool | Actions | Title |',
    '|------|---------|-------|',
    ...rows,
  ].join('\n');
}

/**
 * Replace the block between `<!-- BEGIN:AUTOGEN <section> -->` and its matching
 * END marker. If the markers are absent, the document is left untouched so
 * manual docs don't get clobbered accidentally.
 */
function replaceSection(src, section, newBody) {
  const begin = `<!-- BEGIN:AUTOGEN ${section} -->`;
  const end = `<!-- END:AUTOGEN ${section} -->`;
  const pattern = new RegExp(
    `${escapeRegex(begin)}[\\s\\S]*?${escapeRegex(end)}`,
    'g',
  );
  if (!pattern.test(src)) return { src, replaced: false };
  const replacement = `${begin}\n${newBody}\n${end}`;
  return { src: src.replace(pattern, replacement), replaced: true };
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

async function rewriteFile(path, label, sections) {
  if (!existsSync(path)) {
    console.warn(`[skill:docs] ${label} not found at ${path} — skipping`);
    return;
  }
  let content = await readFile(path, 'utf8');
  const touched = [];
  for (const [section, body] of Object.entries(sections)) {
    const res = replaceSection(content, section, body);
    if (res.replaced) {
      content = res.src;
      touched.push(section);
    }
  }
  if (touched.length === 0) {
    console.warn(`[skill:docs] ${label}: no AUTOGEN markers matched, nothing rewritten`);
    return;
  }
  const tmpPath = `${path}.tmp-${process.pid}-${Date.now()}`;
  await writeFile(tmpPath, content, 'utf8');
  await rename(tmpPath, path);
  console.log(`[skill:docs] ${label}: rewrote sections [${touched.join(', ')}]`);
}

async function main() {
  const counts = await readActionCounts();
  const titles = await readToolTitles();
  const countsBlockForSkill = [
    renderCountsBlock(counts),
    '',
    'Use when: (1) Working with Google Sheets via URL or ID, (2) Analyzing, cleaning, or transforming data,',
    '(3) Creating charts, reports, or dashboards, (4) Building financial models,',
    '(5) Natural language requests like "clean my data", (6) Any mention of Google Sheets, spreadsheets, or sheet data.',
    '',
    'Key capabilities: OAuth 2.1 with PKCE, atomic transactions, task support with cancellation,',
    'MCP elicitation for confirmations, 3-layer context management, comprehensive error handling',
    'with recovery suggestions.',
  ].join('\n');
  const countsBlockForGuide = renderCountsInline(counts);
  const toolTable = renderToolTable(counts, titles);

  await rewriteFile(SKILL_PATH, 'SKILL.md', {
    counts: countsBlockForSkill,
    tools: toolTable,
  });
  await rewriteFile(GUIDE_PATH, 'tool-guide.md', {
    counts: countsBlockForGuide,
    tools: toolTable,
  });

  const toolCount = Object.keys(counts).length;
  const actionCount = Object.values(counts).reduce((s, n) => s + n, 0);
  console.log(`[skill:docs] done — ${toolCount} tools / ${actionCount} actions`);
}

main().catch((err) => {
  console.error('[skill:docs] failed:', err);
  process.exit(1);
});
